import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  /* config options here */
};

export default nextConfig;

import Link from "next/link";
import { Wordmark } from "./wordmark";

const links = [
  { href: "/menu", label: "Menu" },
  { href: "/about", label: "Our story" },
];

export function Nav() {
  return (
    <header className="sticky top-0 z-40 border-b border-crema bg-cream/90 backdrop-blur">
      <nav className="mx-auto flex h-16 max-w-5xl items-center justify-between px-5">
        <Link href="/" className="flex items-center gap-2">
          <Wordmark />
        </Link>
        {/* TODO(demo): nav links are hidden on mobile and there is no menu button yet */}
        <div className="hidden items-center gap-7 text-sm text-roast md:flex">
          {links.map((link) => (
            <Link
              key={link.href}
              href={link.href}
              className="transition-colors hover:text-espresso"
            >
              {link.label}
            </Link>
          ))}
        </div>
        <Link
          href="/menu"
          className="rounded-full bg-terracotta px-4 py-2 text-sm font-medium text-cream transition-colors hover:bg-terracotta-deep"
        >
          Start a subscription
        </Link>
      </nav>
    </header>
  );
}

import type { Coffee } from "@/lib/coffees";
import { ROAST_COLORS } from "@/lib/coffees";

export function CoffeeCard({ coffee }: { coffee: Coffee }) {
  return (
    <article className="flex flex-col rounded-2xl border border-crema bg-foam p-6 transition-shadow hover:shadow-[0_2px_16px_rgba(42,30,22,0.08)]">
      <div className="flex items-center gap-2 text-xs uppercase tracking-widest text-cocoa">
        <span
          className={`h-2.5 w-2.5 rounded-full ${ROAST_COLORS[coffee.roast]}`}
          aria-hidden="true"
        />
        {coffee.roast} roast · {coffee.origin}
      </div>
      <h3 className="mt-3 font-display text-3xl italic">{coffee.name}</h3>
      <p className="mt-2 text-sm leading-relaxed text-cocoa">{coffee.story}</p>
      <div className="mt-4 flex flex-wrap gap-1.5">
        {coffee.notes.map((note) => (
          <span
            key={note}
            className="rounded-full border border-crema bg-cream px-2.5 py-1 text-xs text-roast"
          >
            {note}
          </span>
        ))}
      </div>
      <div className="mt-5 flex items-center justify-between border-t border-crema pt-4">
        <span className="text-sm font-medium">
          ${coffee.price} <span className="text-cocoa">/ 12 oz</span>
        </span>
        {/* TODO(demo): hook this up — there is no cart yet */}
        <button
          type="button"
          className="rounded-full border border-espresso px-4 py-1.5 text-sm font-medium transition-colors hover:bg-espresso hover:text-cream"
        >
          Add to bag
        </button>
      </div>
    </article>
  );
}

export type Roast = "light" | "medium" | "dark" | "decaf";

export type Coffee = {
  slug: string;
  name: string;
  origin: string;
  roast: Roast;
  notes: [string, string, string];
  price: number;
  story: string;
  featured?: boolean;
};

export const ROAST_COLORS: Record<Roast, string> = {
  light: "bg-honey",
  medium: "bg-terracotta",
  dark: "bg-espresso",
  decaf: "bg-sage",
};

export const coffees: Coffee[] = [
  {
    slug: "mananitas",
    name: "Mañanitas",
    origin: "Veracruz, Mexico",
    roast: "medium",
    notes: ["honey", "orange peel", "toasted almond"],
    price: 18,
    story:
      "The one you wake up for. Our house breakfast roast, sweet and steady, from a family farm in the Veracruz highlands.",
    featured: true,
  },
  {
    slug: "paloma",
    name: "Paloma",
    origin: "Huila, Colombia",
    roast: "light",
    notes: ["jasmine", "peach", "lime soda"],
    price: 19,
    story:
      "Bright, floral, a little show-off. Washed process from a women-led cooperative in Huila. Best as a pour-over.",
    featured: true,
  },
  {
    slug: "media-noche",
    name: "Media Noche",
    origin: "Antigua, Guatemala",
    roast: "dark",
    notes: ["dark chocolate", "molasses", "smoke"],
    price: 18,
    story:
      "For late shifts and long talks. Volcanic-soil Antigua taken right to the edge of the roast, never past it.",
    featured: true,
  },
  {
    slug: "cajeta",
    name: "Cajeta",
    origin: "Chiapas, Mexico",
    roast: "medium",
    notes: ["goat-milk caramel", "vanilla", "pecan"],
    price: 20,
    story:
      "Tastes like the candy your tía kept in the good cupboard. Honey-process Chiapas with a dessert finish.",
  },
  {
    slug: "volcan",
    name: "Volcán",
    origin: "Tarrazú, Costa Rica",
    roast: "dark",
    notes: ["brown sugar", "cherry cola", "cedar"],
    price: 19,
    story:
      "Grown on the shoulders of a volcano, roasted like it remembers. Big body, clean finish, great with milk.",
  },
  {
    slug: "nube",
    name: "Nube",
    origin: "Oaxaca, Mexico",
    roast: "decaf",
    notes: ["cocoa", "graham cracker", "plum"],
    price: 17,
    story:
      "All of the ritual, none of the jitters. Sugarcane-decaffeinated Oaxaca lot that drinks like a full-caf medium.",
  },
];

export const featuredCoffees = coffees.filter((c) => c.featured);

import type { Metadata } from "next";
import { Instrument_Sans, Instrument_Serif } from "next/font/google";
import { Nav } from "@/components/nav";
import { Footer } from "@/components/footer";
import "./globals.css";

const instrumentSans = Instrument_Sans({
  variable: "--font-instrument-sans",
  subsets: ["latin"],
});

const instrumentSerif = Instrument_Serif({
  variable: "--font-instrument-serif",
  weight: "400",
  style: ["normal", "italic"],
  subsets: ["latin"],
});

export const metadata: Metadata = {
  metadataBase: new URL("https://cafecito-mu.vercel.app"),
  title: "Cafecito — small-batch coffee, roasted with cariño",
  description:
    "Six coffees, roasted every Tuesday at our shop in Noe Valley, San Francisco — drink them at the long table or have them shipped while they still sing.",
  openGraph: {
    title: "Cafecito — small-batch coffee, roasted with cariño",
    description:
      "A corner roastery and record bar at 4001 26th St, Noe Valley. Six coffees, one roast day, shipped while they still sing.",
    images: ["/photos/exterior.jpg"],
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <body
        className={`${instrumentSans.variable} ${instrumentSerif.variable} font-sans antialiased`}
      >
        <Nav />
        <main>{children}</main>
        <Footer />
      </body>
    </html>
  );
}

"use client";

import { useState } from "react";
import { CoffeeCard } from "@/components/coffee-card";
import { coffees } from "@/lib/coffees";

const roastFilters = ["all", "light", "medium", "dark", "Decaf"];

export default function MenuPage() {
  const [active, setActive] = useState("all");

  const shown =
    active === "all" ? coffees : coffees.filter((c) => c.roast === active);

  return (
    <div className="mx-auto max-w-5xl px-5 py-16">
      <p className="text-xs uppercase tracking-[0.25em] text-terracotta">
        The menu
      </p>
      <h1 className="mt-4 font-display text-5xl tracking-tight sm:text-6xl">
        Six coffees. <em>No filler.</em>
      </h1>
      <p className="mt-4 max-w-xl leading-relaxed text-cocoa">
        Every coffee we sell gets roasted this Tuesday. If it isn&rsquo;t good
        enough to drink black, it doesn&rsquo;t make the menu.
      </p>

      <div className="mt-10 flex flex-wrap gap-2">
        {roastFilters.map((roast) => (
          <button
            key={roast}
            type="button"
            onClick={() => setActive(roast)}
            className={`rounded-full border px-4 py-1.5 text-sm capitalize transition-colors ${
              active === roast
                ? "border-espresso bg-espresso text-cream"
                : "border-crema bg-foam text-roast hover:border-cocoa"
            }`}
          >
            {roast}
          </button>
        ))}
      </div>

      <div className="mt-8 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
        {shown.map((coffee) => (
          <CoffeeCard key={coffee.slug} coffee={coffee} />
        ))}
      </div>
    </div>
  );
}
